import type { PolymorphicProps } from "@kobalte/core/polymorphic";

import { Button, type ButtonProps } from "./button.tsx";
import { Input } from "./input.tsx";
import { Textarea } from "./textarea.tsx";
import { cn } from "~/lib/utils.ts";
import type { VariantProps } from "class-variance-authority";
import { cva } from "class-variance-authority";

import type { Component, ComponentProps, JSX, ValidComponent } from "solid-js";
import { mergeProps, splitProps } from "solid-js";

const InputGroup: Component<ComponentProps<"div">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <div
      data-slot="input-group"
      role="group"
      class={cn(
        "group/input-group bg-input/50 border-transparent has-[[data-slot=input-group-control]:focus-visible]:border-ring has-[[data-slot=input-group-control]:focus-visible]:ring-ring/30 has-[[data-slot][aria-invalid=true]]:ring-destructive/20 has-[[data-slot][aria-invalid=true]]:border-destructive dark:has-[[data-slot][aria-invalid=true]]:ring-destructive/40 h-8 rounded-2xl border transition-[color,box-shadow] duration-200 in-data-[slot=combobox-content]:focus-within:border-inherit in-data-[slot=combobox-content]:focus-within:ring-0 has-[[data-slot=input-group-control]:focus-visible]:ring-3 has-[[data-slot][aria-invalid=true]]:ring-3 has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col has-[>[data-align=block-end]]:[&>input]:pt-3 has-[>[data-align=block-start]]:[&>input]:pb-3 has-[>[data-align=inline-end]]:[&>input]:pr-1.5 has-[>[data-align=inline-start]]:[&>input]:pl-1.5 relative flex w-full min-w-0 items-center outline-none has-[>textarea]:h-auto",
        local.class,
      )}
      {...others}
    />
  );
};

const inputGroupAddonVariants = cva(
  "text-muted-foreground **:data-[slot=kbd]:bg-muted-foreground/10 h-auto gap-2 py-1.5 text-sm font-medium group-data-[disabled=true]/input-group:opacity-50 **:data-[slot=kbd]:rounded-2xl **:data-[slot=kbd]:px-1.5 [&>svg:not([class*='size-'])]:size-4 flex cursor-text items-center justify-center select-none",
  {
    variants: {
      align: {
        "inline-start": "pl-2 has-[>button]:ml-[-0.3rem] has-[>kbd]:ml-[-0.15rem] order-first",
        "inline-end": "pr-2 has-[>button]:mr-[-0.3rem] has-[>kbd]:mr-[-0.15rem] order-last",
        "block-start":
          "px-2.5 pt-2 group-has-[>input]/input-group:pt-2 [.border-b]:pb-2 order-first w-full justify-start",
        "block-end":
          "px-2.5 pb-2 group-has-[>input]/input-group:pb-2 [.border-t]:pt-2 order-last w-full justify-start",
      },
    },
    defaultVariants: {
      align: "inline-start",
    },
  },
);

type InputGroupAddonProps =
  & ComponentProps<"div">
  & VariantProps<typeof inputGroupAddonVariants>;

const InputGroupAddon: Component<InputGroupAddonProps> = (rawProps) => {
  const props = mergeProps({ align: "inline-start" as const }, rawProps);
  const [local, others] = splitProps(props, ["class", "align"]);

  const handleClick: JSX.EventHandler<HTMLDivElement, MouseEvent> = (e) => {
    if ((e.target as HTMLElement).closest("button")) {
      return;
    }
    e.currentTarget.parentElement?.querySelector("input")?.focus();
  };

  return (
    <div
      role="group"
      data-slot="input-group-addon"
      data-align={local.align}
      class={cn(inputGroupAddonVariants({ align: local.align }), local.class)}
      onClick={handleClick}
      {...others}
    />
  );
};

const inputGroupButtonVariants = cva(
  "gap-2 rounded-2xl text-sm flex items-center shadow-none",
  {
    variants: {
      size: {
        xs: "h-6 gap-1 rounded-xl px-1.5 [&>svg:not([class*='size-'])]:size-3.5",
        sm: "",
        "icon-xs": "size-6 rounded-xl p-0 has-[>svg]:p-0",
        "icon-sm": "size-8 p-0 has-[>svg]:p-0",
      },
    },
    defaultVariants: {
      size: "xs",
    },
  },
);

// Kobalte's ButtonRootProps carries only the primitive's own options, so the
// intrinsic element props upstream gets from `ComponentProps<typeof Button>`
// (onClick, title, …) arrive through PolymorphicProps instead.
type InputGroupButtonProps<T extends ValidComponent = "button"> =
  & Omit<ButtonProps<T>, "size">
  & VariantProps<typeof inputGroupButtonVariants>;

const InputGroupButton = <T extends ValidComponent = "button">(
  rawProps: PolymorphicProps<T, InputGroupButtonProps<T>>,
) => {
  const props = mergeProps(
    { type: "button" as const, variant: "ghost" as const, size: "xs" as const },
    rawProps as InputGroupButtonProps,
  );
  const [local, others] = splitProps(props, [
    "class",
    "size",
    "variant",
    "type",
  ]);
  return (
    <Button
      type={local.type}
      data-size={local.size}
      variant={local.variant}
      class={cn(inputGroupButtonVariants({ size: local.size }), local.class)}
      {...others}
    />
  );
};

const InputGroupText: Component<ComponentProps<"span">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <span
      class={cn(
        "text-muted-foreground gap-2 text-sm [&_svg:not([class*='size-'])]:size-4 flex items-center [&_svg]:pointer-events-none",
        local.class,
      )}
      {...others}
    />
  );
};

const InputGroupInput: Component<ComponentProps<"input">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <Input
      data-slot="input-group-control"
      class={cn(
        "rounded-none border-0 bg-transparent shadow-none ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent flex-1",
        local.class,
      )}
      {...others}
    />
  );
};

const InputGroupTextarea: Component<ComponentProps<"textarea">> = (props) => {
  const [local, others] = splitProps(props, ["class"]);
  return (
    <Textarea
      data-slot="input-group-control"
      class={cn(
        "rounded-none border-0 bg-transparent py-2 shadow-none ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent flex-1 resize-none",
        local.class,
      )}
      {...others}
    />
  );
};

export {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupText,
  InputGroupTextarea,
};
